mapper.insert:
INSERT INTO data_sync_status (
    data_type, trade_date, status, success_count,
    fail_count, message, sync_time
) VALUES (
             #{dataType}, #{tradeDate}, #{status}, #{successCount},
             #{failCount}, #{message}, #{syncTime}
         )

mapper.select:
SELECT * FROM data_sync_status
WHERE trade_date = #{tradeDate}
ORDER BY data_type

SELECT * FROM data_sync_status
WHERE data_type = #{dataType} AND trade_date = #{tradeDate}
    LIMIT 1

SELECT * FROM data_sync_status
WHERE trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY sync_time DESC, trade_date DESC, data_type

SELECT * FROM data_sync_status
WHERE data_type = #{dataType}
  AND trade_date BETWEEN #{startDate} AND #{endDate}
ORDER BY sync_time DESC, trade_date DESC
